christen:{n:"Christen Holst",d:"b. c. 1793 · Nordborg, Denmark",b:1793,s:"b",p:["laurensius", "metthe"],r:["dk", "nl"],t:"A ship's mate in the merchant service, born at Nordborg on the Danish island of Als. He married Hendrina Verhoeckx in Amsterdam on 9 May 1832, and had died by 1846.",src:[["Marriage, 1832", "https://www.openarchieven.nl/nha:2A57B623-F124-49BC-BD2F-274F5B4FE795"]]},
hendrinav:{n:"Hendrina Verhoeckx",d:"b. c. 1800 · Nijkerk",b:1800,s:"b",p:["henricusv", "joanna"],r:["nl"],t:"A servant, later a barkeeper in Amsterdam. Widowed, she married the Danish seaman Ole Christiansen in 1846."},
peter:{n:"Peter de Kock",d:"b. c. 1794 · Tilburg",b:1794,s:"b",p:["adriaan", "johannas"],r:["nl"],t:"Married Antonetta Peijnenborg at Tilburg on 31 January 1822.",src:[["Marriage, 1822", "https://www.openarchieven.nl/rat:1115d114-3861-11e0-bcd1-8edf61960649"]]},
