petervb:{n:"Peter van den Brekel",d:"b. 1807 · Goirle",b:1807,s:"b",p:["petervb0", "elisabethk2"],r:["nl"],t:"Born at Goirle on 15 November 1807. Married Aldegonda de Rooij there on 2 May 1829.",src:[["Marriage, 1829", "https://www.openarchieven.nl/bhi:6e9e8fdd-9304-d246-54cf-82b06d3b7ce3"]]},
